    def expr(self):
        result = self.term()
        while self.index < len(self.expression):
            if self.peek() in ('+', '-'):
                op = self.get()
                right = self.term()
                if op == '+':
                    result += right
                elif op == '-':
                    result -= right
            else:
                break
        return result

    def term(self):
        result = self.factor()
        while self.index < len(self.expression):
            if self.peek() in ('*', '/'):
                op = self.get()
                right = self.factor()
                if op == '*':
                    result *= right
                elif op == '/':
                    result /= right
            else:
                break
        return result

    def factor(self):
        if self.peek() == '(':
            self.get()  # consume '('
            result = self.expr()
            self.get()  # consume ')'
            return result
        else:
            return self.number()

    def number(self):
        start = self.index
        while self.index < len(self.expression) and (self.peek().isdigit() or self.peek() == '.'):
            self.get()
        return float(self.expression[start:self.index])

    def get(self):
        char = self.expression[self.index]
        self.index += 1
        return char

    def peek(self):
        if self.index < len(self.expression):
            return self.expression[self.index]
        return ''

