        char = self.expression[self.index]
        self.index += 1

        if char.isdigit() or char == '.':
            num = char
            while self.index < len(self.expression) and (self.expression[self.index].isdigit() or self.expression[self.index] == '.'):
                num += self.expression[self.index]
                self.index += 1
            return float(num)

        if char in '+-*/()':
            return char

        return None

    def parse(self):
        def parse_expression():
            value = parse_term()
            while True:
                token = self.get_next_token()
                if token in ['+', '-']:
                    value = self.perform_operation(value, token, parse_term())
                else:
                    self.index -= 1
                    break
            return value

        def parse_term():
            value = parse_factor()
            while True:
                token = self.get_next_token()
                if token in ['*', '/']:
                    value = self.perform_operation(value, token, parse_factor())
                else:
                    self.index -= 1
                    break
            return value

        def parse_factor():
            token = self.get_next_token()
            if isinstance(token, float):  # number
                return token
            elif token == '(':
                value = parse_expression()
                self.get_next_token()  # consume ')'
                return value
            raise Exception("Unexpected token")

        return parse_expression()

    def perform_operation(self, left: float, op: str, right: float) -> float:
